/**
 * One-time runtime-notice relabel (founder decision 2026-10-23: relabel in
 * place). For each row in the founder-approved receipt, replaces only the
 * misapplied leading `David [Claude Code]:` label with the runtime-notice
 * label. The notice text and the reply after it are never changed.
 *
 * Inert until an approved receipt is committed at RECEIPT_PATH (generated by
 * server/scripts/generate-runtime-notice-relabel-receipt.ts and approved by
 * the founder as an exact list). Idempotent, and fail-closed per row, with
 * the row locked (FOR UPDATE) while it is checked and changed:
 *   - the row has per-turn attribution now: leave it untouched (changing its
 *     bytes would invalidate that attribution's hashes) and report it;
 *   - current content hashes to preSha256: apply the label span, verify the
 *     result hashes to postSha256, commit;
 *   - current content hashes to postSha256: already applied, skip;
 *   - anything else: the row drifted; leave it untouched and report it.
 * Only the exact permitted notice label is ever written, whatever the receipt
 * says. One untouched row never blocks the others or a deploy. Reversal:
 * replace the new label with the old one for the same rows; preSha256 proves it.
 */
import { createHash } from 'node:crypto';
import { existsSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import type { Pool } from '@neondatabase/serverless';
import type { DataOpResult } from '../run-data-ops';
import { RUNTIME_NOTICE_LABEL } from '../../server/services/runtime-notice-relabel';
import {
  PERMITTED_EPISODE_ID, episodeReceiptProblem, episodeSourceProblem, relabelEpisodeContent, type EpisodeReceipt, type SourceEntry,
} from '../../server/services/runtime-notice-relabel-episode';

export const RECEIPT_PATH = join(dirname(fileURLToPath(import.meta.url)), 'relabel-runtime-notices.receipt.json');
export const EPISODE_RECEIPT_PATH = join(dirname(fileURLToPath(import.meta.url)), 'relabel-runtime-notices.episode-receipt.json');

const OLD_LABEL = 'David [Claude Code]:';
const NEW_LABEL = `${RUNTIME_NOTICE_LABEL}:`;
const sha256 = (text: string) => createHash('sha256').update(text, 'utf8').digest('hex');

export interface RelabelEntry {
  rowId: string;
  offset: 0;
  oldLabel: string;
  newLabel: string;
  preSha256: string;
  postSha256: string;
}

export interface RelabelReceipt {
  kind: string;
  label: string;
  entries: RelabelEntry[];
  listSha256: string;
}

export type RowOutcome = { status: 'apply'; next: string } | { status: 'already-applied' } | { status: 'drifted' };

/** Decide one row from its current content. Pure; the only way content changes. */
export function relabelContent(content: string, entry: RelabelEntry): RowOutcome {
  if (entry.offset !== 0 || entry.oldLabel !== OLD_LABEL || entry.newLabel !== NEW_LABEL) return { status: 'drifted' };
  const hash = sha256(content);
  if (hash === entry.postSha256) return { status: 'already-applied' };
  if (hash !== entry.preSha256 || !content.startsWith(`${OLD_LABEL} `)) return { status: 'drifted' };
  const next = NEW_LABEL + content.slice(OLD_LABEL.length);
  return sha256(next) === entry.postSha256 ? { status: 'apply', next } : { status: 'drifted' };
}

/** The connection surface applyReceipt needs; a real Pool provides it. */
export interface RelabelPool {
  connect(): Promise<{ query(sql: string, params?: unknown[]): Promise<{ rows: any[] }>; release(): void }>;
}

/** Apply one approved receipt. Exported so the transaction rules are tested with a fake pool. */
export async function applyReceipt(pool: RelabelPool, receipt: RelabelReceipt): Promise<DataOpResult & { counts: Record<string, number> }> {
  if (receipt.kind !== 'runtime-notice-relabel-rows' || receipt.label !== RUNTIME_NOTICE_LABEL) {
    throw new Error('receipt is not a runtime-notice relabel for the permitted label');
  }
  if (sha256(JSON.stringify(receipt.entries)) !== receipt.listSha256) throw new Error('receipt list hash does not match its entries');
  const counts = { applied: 0, alreadyApplied: 0, drifted: 0, attributed: 0 };
  const untouched: string[] = [];
  for (const entry of receipt.entries) {
    const client = await pool.connect();
    try {
      await client.query('BEGIN');
      const { rows } = await client.query(
        'SELECT content, attribution FROM conversation_memories WHERE id = $1 FOR UPDATE', [entry.rowId],
      );
      if (rows.length && rows[0].attribution !== null && rows[0].attribution !== undefined) {
        counts.attributed++;
        untouched.push(entry.rowId);
      } else {
        const outcome = rows.length ? relabelContent(rows[0].content, entry) : { status: 'drifted' as const };
        if (outcome.status === 'apply') {
          await client.query('UPDATE conversation_memories SET content = $2 WHERE id = $1', [entry.rowId, outcome.next]);
          counts.applied++;
        } else if (outcome.status === 'already-applied') {
          counts.alreadyApplied++;
        } else {
          counts.drifted++;
          untouched.push(entry.rowId);
        }
      }
      await client.query('COMMIT');
    } catch (e) {
      await client.query('ROLLBACK');
      throw e;
    } finally {
      client.release();
    }
  }
  const detail = `relabelled ${counts.applied}, already applied ${counts.alreadyApplied}, ` +
    `left unchanged: drifted ${counts.drifted}, attributed ${counts.attributed}` +
    (untouched.length ? ` (${untouched.slice(0, 10).join(', ')}${untouched.length > 10 ? ', ...' : ''})` : '');
  return { applied: counts.applied > 0, detail, counts };
}

/**
 * Apply one approved episode receipt (server/services/runtime-notice-relabel-episode.ts)
 * to its rolling episode row, atomically, with the row locked. A row with
 * attribution, a receipt that fails its structural checks, or a prefix that
 * changed leaves the episode untouched and reported. Appends that land while
 * the row is locked are applied after it, by their own atomic `content || ...`.
 */
export async function applyEpisodeReceipt(
  pool: RelabelPool,
  receipt: EpisodeReceipt,
  rowsReceipt: { listSha256: string; entries: SourceEntry[] },
  expectedEpisodeId: string,
): Promise<{ status: string; detail: string }> {
  // The target comes from the caller (production: PERMITTED_EPISODE_ID), never from the receipt itself.
  const problem = episodeReceiptProblem(receipt, expectedEpisodeId);
  if (problem) throw new Error(`episode receipt refused: ${problem}`);
  if (sha256(JSON.stringify(rowsReceipt.entries)) !== rowsReceipt.listSha256) throw new Error('row receipt list hash does not match its entries');
  if (receipt.sourceReceiptListSha256 !== rowsReceipt.listSha256) throw new Error('episode receipt is not bound to the approved row receipt');
  const sourceProblem = episodeSourceProblem(receipt, rowsReceipt.entries);
  if (sourceProblem) throw new Error(`episode receipt refused: ${sourceProblem}`);
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const { rows } = await client.query(
      'SELECT content, attribution FROM conversation_memories WHERE id = $1 FOR UPDATE', [receipt.episodeId],
    );
    let status: string;
    let detail: string;
    if (!rows.length) {
      status = 'drifted'; detail = 'episode row not found';
    } else if (rows[0].attribution !== null && rows[0].attribution !== undefined) {
      status = 'attributed'; detail = 'episode row has per-turn attribution; left unchanged';
    } else {
      const outcome = relabelEpisodeContent(rows[0].content, receipt);
      if (outcome.status === 'apply') {
        await client.query('UPDATE conversation_memories SET content = $2 WHERE id = $1', [receipt.episodeId, outcome.next]);
        status = 'applied'; detail = `relabelled ${receipt.edits.length} episode label(s)`;
      } else if (outcome.status === 'already-applied') {
        status = 'already-applied'; detail = 'already applied';
      } else {
        status = 'drifted'; detail = `${outcome.reason}; left unchanged`;
      }
    }
    await client.query('COMMIT');
    return { status, detail: `episode ${receipt.episodeId}: ${detail}` };
  } catch (e) {
    await client.query('ROLLBACK');
    throw e;
  } finally {
    client.release();
  }
}

export async function run(pool: Pool): Promise<DataOpResult> {
  if (!existsSync(RECEIPT_PATH)) return { applied: false, detail: 'no approved receipt committed; nothing to do' };
  const rowsReceipt = JSON.parse(readFileSync(RECEIPT_PATH, 'utf8')) as RelabelReceipt;
  const rowsResult = await applyReceipt(pool as unknown as RelabelPool, rowsReceipt);
  if (!existsSync(EPISODE_RECEIPT_PATH)) return { applied: rowsResult.applied, detail: `${rowsResult.detail}; no episode receipt committed` };
  const episodeResult = await applyEpisodeReceipt(
    pool as unknown as RelabelPool, JSON.parse(readFileSync(EPISODE_RECEIPT_PATH, 'utf8')) as EpisodeReceipt,
    rowsReceipt as unknown as { listSha256: string; entries: SourceEntry[] }, PERMITTED_EPISODE_ID,
  );
  return { applied: rowsResult.applied || episodeResult.status === 'applied', detail: `${rowsResult.detail}; ${episodeResult.detail}` };
}
